package com.melonman106.vbvclient;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiGraphicsExtractor;
public final class VBVCrosshair { private VBVCrosshair(){} public static void render(GuiGraphicsExtractor g){if(!VBVCrosshairConfig.enabled)return;Minecraft m=Minecraft.getInstance();int side=15;int scale=VBVCrosshairConfig.size;int ox=m.getWindow().getGuiScaledWidth()/2-(side*scale)/2,oy=m.getWindow().getGuiScaledHeight()/2-(side*scale)/2;for(int y=0;y<side;y++)for(int x=0;x<side;x++)if(VBVCrosshairConfig.pixels[y*15+x])g.fill(ox+x*scale,oy+y*scale,ox+x*scale+scale,oy+y*scale+scale,VBVCrosshairConfig.color);}}
